    /* ---- Research Mega Dropdown (DESKTOP ONLY) ---- */
    #nav-research { position: relative !important; }
    .mega-dropdown {
        display: none;
        position: absolute;
        top: 100%;
        left: 0;
        width: 520px;
        background: #fff;
        border-top: 3px solid #f07020;
        box-shadow: 0 8px 28px rgba(0,0,0,0.14);
        z-index: 9999;
    }
    .mega-dropdown * { box-sizing: border-box; }
    #nav-research:hover .mega-dropdown { display: block; }
    .mega-top {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 20px;
        padding: 18px 22px 16px;
        border-bottom: 1px solid #eee;
        background: #f8f9fa;
        text-align: left;
    }
    .mega-heading {
        font-size: 14px;
        font-weight: 700;
        color: #283747;
        text-transform: uppercase;
        letter-spacing: .05em;
        margin: 0 0 4px 0;
        padding: 0;
    }
    .mega-desc {
        font-size: 11.5px;
        color: #888;
        line-height: 1.5;
        max-width: 260px;
        margin: 0;
        padding: 0;
        text-transform: none;
        letter-spacing: normal;
        font-weight: 400;
    }
    .mega-cta {
        flex-shrink: 0;
        display: inline-flex;
        align-items: center;
        gap: 6px;
        background: #283747;
        color: #fff !important;
        font-size: 11px;
        font-weight: 700;
        text-transform: uppercase;
        letter-spacing: .07em;
        padding: 8px 13px;
        text-decoration: none !important;
        white-space: nowrap;
        transition: background .2s;
        line-height: 1;
    }
    .mega-cta:hover { background: #1a2530; color: #fff !important; text-decoration: none !important; }
    .mega-cta svg {
        width: 10px;
        height: 10px;
        fill: none;
        stroke: #f07020;
        stroke-width: 2.5;
        stroke-linecap: round;
        stroke-linejoin: round;
        flex-shrink: 0;
    }
    .mega-centers-label {
        padding: 11px 22px 5px;
        font-size: 9.5px;
        font-weight: 700;
        text-transform: uppercase;
        letter-spacing: .13em;
        color: #bbb;
        text-align: left;
    }
    .mega-grid {
        display: grid;
        grid-template-columns: 1fr 1fr;
        padding: 4px 14px 10px;
        gap: 0;
        text-align: left;
    }
    .mega-item {
        display: flex !important;
        flex-direction: row !important;
        align-items: center !important;
        flex-wrap: nowrap !important;
        gap: 9px;
        padding: 7px 8px;
        text-decoration: none !important;
        border-left: 2px solid transparent;
        transition: background .15s, border-color .15s;
        min-width: 0;
        width: 100%;
    }
    .mega-item:hover {
        background: #f3f6f9;
        border-left-color: #f07020;
        text-decoration: none !important;
    }
    .mega-icon {
        width: 28px;
        height: 28px;
        min-width: 28px !important;
        max-width: 28px !important;
        background: #edf0f4;
        display: flex !important;
        align-items: center !important;
        justify-content: center !important;
        flex-shrink: 0 !important;
        flex-grow: 0 !important;
        transition: background .15s;
        float: none !important;
    }
    .mega-item:hover .mega-icon { background: #283747; }
    .mega-icon i.fa {
        font-size: 13px;
        color: #283747;
        transition: color .15s;
        line-height: 1;
        display: block !important;
        float: none !important;
        width: auto !important;
        height: auto !important;
        margin: 0 !important;
        padding: 0 !important;
    }
    .mega-item:hover .mega-icon i.fa { color: #f07020; }
    .mega-item-text {
        font-size: 11px;
        font-weight: 600;
        color: #283747;
        line-height: 1.3;
        text-transform: uppercase;
        letter-spacing: .03em;
        text-align: left;
        flex: 1 1 auto !important;
        min-width: 0;
        display: inline !important;
        float: none !important;
    }
    .mega-item:hover .mega-item-text { color: #283747; }
    /* ---- Desktop only: hide native ul (no !important so site JS can still open on mobile) ---- */
    @media (min-width: 992px) {
        #nav-research > ul.dropdown { display: none !important; }
    }
    /* ---- Mobile: kill mega entirely, native dropdown takes over ---- */
    @media (max-width: 991px) {
        .mega-dropdown { display: none !important; }
        #nav-research:hover .mega-dropdown { display: none !important; }
    }











































