        border-top: 3px solid #f07020;
        box-shadow: 0 8px 28px rgba(0,0,0,0.14);
        z-index: 9999;
    }
    .mega-dropdown * { box-sizing: border-box; }
    #nav-research:hover .mega-dropdown { display: block; }
    .mega-top {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 20px;
        padding: 18px 22px 16px;
        border-bottom: 1px solid #eee;
        background: #f8f9fa;
        text-align: left;
    }
    .mega-heading {
        font-size: 14px;
        font-weight: 700;
        color: #283747;
        text-transform: uppercase;
        letter-spacing: .05em;
        margin: 0 0 4px 0;
        padding: 0;
    }
    .mega-desc {
        font-size: 11.5px;
        color: #888;
        line-height: 1.5;
        max-width: 260px;
        margin: 0;
        padding: 0;
        text-transform: none;
        letter-spacing: normal;
        font-weight: 400;
    }
    .mega-cta {
        flex-shrink: 0;
        display: inline-flex;
        align-items: center;
        gap: 6px;
        background: #283747;
        color: #fff !important;
        font-size: 11px;
        font-weight: 700;
        text-transform: uppercase;
        letter-spacing: .07em;
        padding: 8px 13px;
        text-decoration: none !important;
        white-space: nowrap;
        transition: background .2s;
        line-height: 1;
    }
    .mega-cta:hover { background: #1a2530; color: #fff !important; text-decoration: none !important; }
